const pages={
'guest-engagement-platform':{title:'Guest Engagement Platform for Cruise Lines, Hotels & Resorts | Tisonik',desc:'Tisonik is a guest engagement platform for cruise lines, hotels and resorts, connecting participation, service recovery, recognition and ancillary revenue.',eyebrow:'Category',h1:'A guest engagement platform built around action, not another dashboard',lead:'Tisonik gives cruise lines, hotels and resorts one operating layer for guest participation, positive recognition, real-time service recovery and relevant revenue opportunities.',tags:['Guest engagement platform','Guest experience software','Cruise + hotels & resorts'],problems:['Engagement lives across disconnected surveys, campaigns, apps and service desks.','Service signals often arrive after the guest has left, when recovery is too late.','Revenue offers are frequently broad rather than connected to real guest intent.'],outcomes:['Increase participation','Turn live guest signals into operational action instead of post-stay reporting.','Recover issues faster','Route low experience signals to the right team while there is still time to improve the stay or sailing.','Create relevant revenue','Use declared interests and participation context to surface suitable activities and offers.'],workflow:['Capture','Collect structured participation, recognition and experience signals inside the existing digital journey.','Route','Send service, engagement and commercial signals to the right operational role.','Measure','Connect participation, recovery and commercial outcomes at property or sailing level.'],faq:[['What is a guest engagement platform?','A guest engagement platform coordinates guest-facing participation with the operational actions behind it. Tisonik focuses specifically on engagement, recovery, recognition and ancillary revenue for cruise lines, hotels and resorts.'],['Does Tisonik replace a hotel or cruise app?','No. Tisonik is designed to embed in or sit alongside an existing guest app and operational stack.'],['Is Tisonik a survey tool?','No. Feedback is one signal. The platform is designed to turn signals into participation, recovery workflows and relevant next actions.']],related:[['Cruise','/cruise/'],['Hotels & Resorts','/hotels-resorts/'],['Service recovery','/service-recovery/'],['Ancillary revenue','/ancillary-revenue/']]},
'cruise':{title:'Tisonik Cruise | Guest Engagement Platform for Cruise Lines',desc:'Tisonik Cruise helps cruise lines increase passenger participation, recognize crew, recover service issues during the sailing and create relevant onboard revenue opportunities.',eyebrow:'Tisonik Cruise',h1:'Turn more onboard moments into participation, recovery and revenue',lead:'Tisonik Cruise adds a structured engagement layer to the cruise line’s existing digital journey—without turning the product into another social network or replacing onboard systems.',tags:['Cruise guest engagement','Add-to-app','Sailing-scoped'],problems:['Passengers miss activities and offers because discovery is fragmented across schedules, signage and push messages.','Private service problems can remain invisible until post-cruise surveys.','Positive crew interactions are rarely captured in a structured, measurable way.'],outcomes:['More participation','Run paperless live campaigns, activity check-ins, polls, trivia and targeted draws.','Better recovery','Escalate low experience signals and track acknowledgement, assignment, resolution and post-recovery pulse.','Stronger onboard economics','Connect interests and engagement context to relevant cruise-line inventory while the cruise line keeps checkout and fulfilment.'],workflow:['Embed','Launch Tisonik Cruise from the existing cruise app using sailing-scoped guest context.','Engage','Offer recognition, structured passenger interaction, participation and experience pulse in one layer.','Operate','Give Director, Guest Services, Activities, Marketing, Sales and Crew Leads role-specific controls.'],faq:[['Does Tisonik require a new passenger app?','No. The target architecture is a white-label add-to-app module or embedded web experience inside the cruise line’s digital environment.'],['Can it work with poor public internet?','The platform is designed around ship-local and offline-tolerant operation. The current pilot uses cloud shared state; ship-local synchronization is part of production integration.'],['Who controls pricing and payments?','The cruise line does. Tisonik can create a relevant handoff and attribution signal without becoming the merchant.']],related:[['Cruise mobile app engagement','/cruise-mobile-app-engagement/'],['Cruise service recovery','/cruise-service-recovery/'],['Cruise guest feedback','/cruise-guest-feedback/'],['Cruise onboard revenue','/cruise-onboard-revenue/']]},
'cruise-guest-engagement':{title:'Cruise Guest Engagement Software | Tisonik Cruise',desc:'Cruise guest engagement software for participation, crew recognition, service recovery and relevant onboard engagement throughout the sailing.',eyebrow:'Cruise engagement',h1:'Make the cruise app useful between booking and checkout',lead:'Tisonik Cruise turns the digital guest journey into a live participation and service layer during the sailing—when engagement can still change the passenger experience.',tags:['Cruise guest engagement','Passenger participation','Onboard experience'],problems:['App usage often falls after schedule checking and basic account tasks.','Passengers face too many generic messages and too little context.','Onboard teams lack a shared view of positive and negative interaction signals.'],outcomes:['Give guests reasons to return','Live participation, recognition and structured prompts create repeat utility during the sailing.','Keep interaction bounded','Predefined affirmations and public-place activity proposals create positive interaction without unrestricted chat.','Connect engagement to operations','High and low signals can route to recognition, activities, recovery or relevant commercial opportunities.'],workflow:['Invite','Surface a contextually relevant action—recognize, join, rate, check in or explore.','Respond','Capture a small structured response instead of asking for long forms.','Act','Use the response to update participation, route a service action or create a relevant handoff.'],faq:[['Is this a social network for passengers?','No. Tisonik Cruise deliberately limits passenger interaction and is not positioned as a dating or unrestricted chat product.'],['Can passenger engagement be targeted?','Yes. Campaigns can be scoped by sailing and can use approved age or interest criteria.'],['Does it support crew recognition?','Yes. Named, contextual crew recognition is a core engagement workflow.']],related:[['Tisonik Cruise','/cruise/'],['Guest participation','/guest-participation/'],['Crew & staff recognition','/crew-and-staff-recognition/']]},
'cruise-mobile-app-engagement':{title:'Cruise Mobile App Engagement | Tisonik Cruise',desc:'Increase cruise mobile app engagement with embedded participation, service recovery, recognition and relevant activity or revenue actions.',eyebrow:'Cruise mobile app',h1:'Add an engagement layer without rebuilding the cruise app',lead:'Tisonik Cruise is designed to plug into an existing cruise-line app and turn authenticated sailing context into useful guest actions and role-based staff workflows.',tags:['Cruise mobile app','Embedded module','API-ready'],problems:['Rebuilding mature cruise apps to test new engagement ideas is slow and expensive.','Point features often require separate authentication and break the guest journey.','Operational teams need controls that consumer-facing app screens do not provide.'],outcomes:['Pilot faster','Test a bounded engagement module before committing to a large host-app rebuild.','Reuse verified context','Use host-provided sailing, guest and permission context instead of creating another passenger account.','Keep host control','The cruise line retains identity, itinerary, inventory, pricing and payment systems.'],workflow:['Host context','The cruise app launches Tisonik with signed sailing-scoped context.','Module action','The passenger completes a Tisonik workflow inside the branded journey.','Host handoff','Bookings or other host-owned actions return to the cruise line with agreed attribution context.'],faq:[['What integration pattern does Tisonik use?','The target pattern is a signed embedded module with APIs/adapters for host identity, sailing manifest, crew roster and activity/inventory systems.'],['Can we start before all integrations are complete?','Yes. A controlled pilot can simulate or manually bridge selected integrations while validating guest and staff workflows.'],['Does Tisonik need payment-card data?','No. The preferred model hands commercial transactions back to the cruise line.']],related:[['Tisonik Cruise','/cruise/'],['Guest engagement platform','/guest-engagement-platform/'],['Request a pilot','/request-pilot/']]},
'cruise-service-recovery':{title:'Cruise Service Recovery Software | Tisonik Cruise',desc:'Real-time cruise service recovery software that turns low guest experience signals into acknowledged, assigned and measurable onboard recovery workflows.',eyebrow:'Cruise service recovery',h1:'Recover the experience while the passenger is still onboard',lead:'Tisonik Cruise connects private guest signals with a structured recovery lifecycle so teams can acknowledge, assign, resolve and measure the outcome before disembarkation.',tags:['Real-time recovery','Guest Services','Experience Pulse'],problems:['Post-cruise surveys identify issues after the recovery window has closed.','Frontline complaints can disappear into informal handoffs.','Teams often measure case closure but not whether the guest actually felt recovered.'],outcomes:['Detect earlier','Low Experience Pulse scores can create or connect to a service recovery workflow.','Create accountability','Move issues through submitted, acknowledged, assigned, resolved and closed states.','Measure the recovery','Ask the passenger for a post-recovery 1–5 pulse rather than assuming resolution equals satisfaction.'],workflow:['Signal','Guest submits an issue or a low pulse creates a recovery opportunity.','Ownership','Guest Services acknowledges and assigns the issue to the right operational owner.','Close the loop','The issue is resolved and the passenger receives a post-recovery pulse.'],faq:[['Is Tisonik an emergency channel?','No. Safety and emergency procedures remain with the cruise line. Tisonik is for service experience recovery.'],['Can we track recovery performance?','Yes. The workflow can measure acknowledgement, assignment, resolution and post-recovery satisfaction.'],['Does the guest have to write a long complaint?','No. Tisonik is designed for low-friction structured signals, with detail added only when needed.']],related:[['Service recovery','/service-recovery/'],['Cruise guest feedback','/cruise-guest-feedback/'],['Tisonik Cruise','/cruise/']]},
'cruise-guest-feedback':{title:'Cruise Guest Feedback Software | Tisonik Cruise',desc:'Collect structured cruise guest feedback during the sailing and route signals into recognition, service recovery and final-night experience measurement.',eyebrow:'Cruise guest feedback',h1:'Move guest feedback from post-cruise reporting to live operations',lead:'Tisonik Cruise uses short, structured prompts so positive and negative signals can trigger the right action while the sailing is still in progress.',tags:['Experience Pulse','In-sailing feedback','Final-night pulse'],problems:['Long surveys depress participation.','Feedback is often separated from the team that can act on it.','Positive signals rarely create recognition or advocacy workflows.'],outcomes:['Reduce friction','Use 1–5 pulses and structured choices when a long free-text survey is unnecessary.','Route by signal','Low scores can open recovery; high scores can route toward recognition.','Create an end-of-cruise pulse','A six-department final-night rating can be completed in under two minutes and linked to a completion-based prize draw.'],workflow:['Ask briefly','Collect a contextual score at the right moment.','Interpret','Classify the signal as recognition, neutral measurement or recovery opportunity.','Follow through','Trigger the appropriate guest or staff workflow and preserve sailing-level reporting.'],faq:[['Is the final-night pulse anonymous?','Deployment configuration determines identity handling, but the pilot is designed around verified completion while minimizing unnecessary public exposure.'],['Can feedback enter a prize draw?','Yes. The pilot includes a separate completion-based final-night draw workflow with configurable winners and age-appropriate prizes.'],['Can high scores trigger crew recognition?','Yes. Positive experience signals can be routed toward recognition.']],related:[['Guest feedback','/guest-feedback/'],['Cruise service recovery','/cruise-service-recovery/'],['Digital raffles & campaigns','/digital-raffles-and-campaigns/']]},
'cruise-onboard-revenue':{title:'Cruise Onboard Revenue & Ancillary Engagement | Tisonik',desc:'Create more relevant cruise onboard revenue opportunities by connecting passenger participation and declared interests to cruise-line activities and inventory.',eyebrow:'Cruise revenue',h1:'Create revenue opportunities from relevance, not more generic push',lead:'Tisonik helps cruise lines connect voluntary guest interests and participation context to the right onboard activity or offer while preserving cruise-line ownership of inventory, pricing and checkout.',tags:['Onboard revenue','Ancillary revenue','Relevant offers'],problems:['Generic promotions compete for attention and can train passengers to ignore the app.','Perishable onboard inventory has a narrow conversion window.','Attribution is difficult when engagement and booking journeys are disconnected.'],outcomes:['Improve relevance','Use declared interests and campaign context to decide which opportunities are worth surfacing.','Protect the guest relationship','Keep the cruise line as merchant and fulfilment owner.','Measure handoffs','Record agreed referral or attribution events so pilots can evaluate incremental commercial value.'],workflow:['Intent signal','Passenger expresses an interest, joins an activity or engages with a relevant campaign.','Opportunity','Tisonik surfaces a suitable cruise-line action rather than a broad catalogue.','Booking handoff','The guest continues in the cruise line’s booking environment with attribution context.'],faq:[['Does Tisonik set cruise prices?','No. Inventory, pricing, payments, refunds and fulfilment stay with the cruise line.'],['Is this only upselling?','No. Revenue is one outcome of a broader engagement platform. The same guest signal may be better used for participation or service recovery.'],['Can sales teams create promotions?','The pilot includes Marketing and Sales/Revenue roles for controlled promotional workflows.']],related:[['Ancillary revenue','/ancillary-revenue/'],['Promotions & rewards','/promotions-and-rewards/'],['Tisonik Cruise','/cruise/']]},
'hotels-resorts':{title:'Tisonik for Hotels & Resorts | Guest Engagement Platform',desc:'Tisonik helps hotels and resorts increase guest participation, recover service issues faster and create more relevant ancillary revenue opportunities.',eyebrow:'Hotels & Resorts',h1:'Turn the stay into an active guest relationship',lead:'Tisonik brings participation, service recovery and revenue intelligence into one guest engagement layer for hotels and resorts—before, during and immediately around the stay.',tags:['Hotels','Resorts','Guest engagement'],problems:['Guest messaging, feedback, activities and upselling often sit in separate tools.','Property teams may learn about dissatisfaction at checkout or after an OTA review.','Resort activities and ancillary services need demand while capacity is still available.'],outcomes:['Engage during the stay','Use activities, campaigns, check-ins, polls and relevant prompts to increase participation.','Recover before checkout','Turn low guest signals into owned service workflows with a post-recovery pulse.','Grow ancillary spend','Connect interests and stay context to spa, dining, activities, upgrades and other property-owned opportunities.'],workflow:['Connect','Launch Tisonik from the property’s guest web/app journey or approved communication touchpoint.','Engage','Capture participation, recognition, feedback and interest signals with low friction.','Act','Route operations to service teams and commercial opportunities to the property’s existing booking flow.'],faq:[['Does Tisonik replace a PMS?','No. Tisonik is an engagement layer. PMS, CRS, POS and other systems remain systems of record.'],['Can a resort use the same platform as a city hotel?','Yes. Resorts may use more participation and activity workflows; hotels may focus more on recovery, recognition and relevant ancillary offers.'],['Can Tisonik work without a native hotel app?','Yes. The architecture can support embedded web experiences as well as host-app integration.']],related:[['Hotel guest experience software','/hotel-guest-experience-software/'],['Hotel guest app','/hotel-guest-app/'],['Hotel upselling software','/hotel-upselling-software/'],['Resort app','/resort-app/']]},
'hotel-guest-experience-software':{title:'Hotel Guest Experience Software | Tisonik',desc:'Hotel guest experience software that connects engagement, service recovery, staff recognition and ancillary revenue in one operational guest layer.',eyebrow:'Hotel guest experience software',h1:'Guest experience software should improve the stay, not just measure it',lead:'Tisonik turns live guest signals into property actions: increase participation, recognize positive moments, recover service problems and create relevant next-step opportunities.',tags:['Hotel guest experience software','Service intelligence','Guest journey'],problems:['Experience platforms can become reporting layers rather than operational tools.','Guest feedback often lacks a clear owner and resolution loop.','Commercial messages are rarely informed by service context.'],outcomes:['Create operational intelligence','Translate guest signals into role-specific actions instead of another dashboard queue.','Protect experience before revenue','A guest with an unresolved service issue should not receive the same commercial journey as a delighted guest.','Connect positive moments','Recognition and high experience signals can strengthen staff feedback and guest advocacy.'],workflow:['Sense','Capture low-friction feedback, participation and interest context.','Prioritize','Use the signal type and guest state to choose recovery, recognition, engagement or a commercial action.','Measure','Track both operational resolution and the guest’s response afterward.'],faq:[['How is this different from reputation management?','Reputation management focuses heavily on reviews and post-stay sentiment. Tisonik focuses on in-stay engagement and operational action.'],['Can Tisonik connect to hotel systems?','The production architecture is designed for adapters to identity, PMS, guest app and property inventory systems.'],['Is it suitable for groups?','Yes. The platform concept is multi-property and enterprise-oriented, with property-level execution and group-level patterns.']],related:[['Hotels & Resorts','/hotels-resorts/'],['Service recovery','/service-recovery/'],['Guest feedback','/guest-feedback/']]},
'hotel-guest-app':{title:'Hotel Guest App Engagement | Tisonik',desc:'Add participation, real-time service recovery, recognition and relevant ancillary actions to an existing hotel guest app or web journey.',eyebrow:'Hotel guest app',h1:'Give the hotel guest app a job after check-in',lead:'Tisonik adds useful in-stay actions to the hotel’s existing digital guest journey without forcing the property to replace its app, PMS or booking stack.',tags:['Hotel guest app','In-stay engagement','Embedded experience'],problems:['Many hotel apps concentrate on check-in, keys and static information.','Guests still revert to calls, desks or messaging for service issues.','Activities and amenities can remain disconnected from the main digital journey.'],outcomes:['Increase in-stay utility','Add structured participation, feedback and service actions guests can complete quickly.','Reduce handoff friction','Route issues and guest intent to the right property role.','Keep booking ownership','Use the property’s existing commerce and fulfilment systems for paid services.'],workflow:['Launch','Open Tisonik from the hotel app, mobile web or approved guest journey.','Act','Guest joins, rates, recognizes, requests recovery or explores a relevant opportunity.','Return','Operational and commercial handoffs continue in the property’s established systems.'],faq:[['Does Tisonik include mobile key?','No. Tisonik is not a replacement for core hotel app utilities. It complements them with engagement and service intelligence.'],['Can it run as mobile web?','Yes. A responsive embedded web experience can support properties without a full native app.'],['What data does it need?','The minimum useful context is a verified stay identity, property/stay scope and the permissions required for the enabled workflows.']],related:[['Hospitality mobile app','/hospitality-mobile-app/'],['Hotels & Resorts','/hotels-resorts/'],['Request a pilot','/request-pilot/']]},
'hospitality-mobile-app':{title:'Hospitality Mobile App Engagement Platform | Tisonik',desc:'A hospitality mobile engagement layer for hotels and resorts that connects guest participation, feedback, service recovery and ancillary actions.',eyebrow:'Hospitality mobile app',h1:'Add operational engagement to the mobile guest journey',lead:'Tisonik helps hotel and resort teams turn mobile touchpoints into measurable participation, faster recovery and more relevant property actions.',tags:['Hospitality mobile app','Guest engagement','Hotels & resorts'],problems:['Mobile journeys are often built feature-by-feature without a shared engagement model.','Guest signals can be trapped in messaging or survey tools.','Operations and revenue teams work from different views of the same guest journey.'],outcomes:['Unify action types','Use one structured layer for participation, feedback, recognition, recovery and commercial handoffs.','Create role clarity','Route each signal to the property role that can actually act on it.','Measure by property and journey','Evaluate adoption and outcomes without forcing every property to redesign its core stack.'],workflow:['Context','Receive approved guest and stay context from the host journey.','Engagement','Present a small, relevant action rather than a generic feature menu.','Operational handoff','Send the resulting signal to the right Tisonik workflow or host system.'],faq:[['Is this only for hotel groups with native apps?','No. Mobile web and embedded experiences can support properties at different levels of digital maturity.'],['Can branding be white-label?','Yes. The platform is designed to operate under the hotel or resort brand.'],['Can different properties enable different modules?','Yes. A pilot can start with selected workflows and expand by property or use case.']],related:[['Hotel guest app','/hotel-guest-app/'],['Hotel guest experience software','/hotel-guest-experience-software/'],['Guest engagement platform','/guest-engagement-platform/']]},
'resort-app':{title:'Resort Guest App & Engagement Platform | Tisonik',desc:'Resort guest engagement for activities, participation, service recovery, recognition and relevant ancillary opportunities throughout the stay.',eyebrow:'Resort app',h1:'Help resort guests discover, participate and recover without more friction',lead:'Resorts have dense activity calendars, multiple outlets and long on-property dwell time. Tisonik turns that complexity into structured engagement and actionable guest signals.',tags:['Resort app','Activities','Ancillary revenue'],problems:['Guests can miss activities and outlets simply because discovery is fragmented.','Capacity-sensitive experiences need better timing than static promotion.','Service issues can cross departments and lose ownership.'],outcomes:['Increase activity participation','Run digital check-ins, live campaigns and interest-led discovery around resort programming.','Coordinate recovery','Route issues across departments while preserving one guest-facing resolution loop.','Surface relevant services','Connect intent to spa, dining, premium activities or other resort-owned inventory.'],workflow:['Discover','Guest sees a relevant activity, prompt or campaign.','Participate','Check in, join, vote, answer or express interest with minimal friction.','Extend','Use the same context for recognition, follow-up, recovery or a relevant commercial handoff.'],faq:[['Can Tisonik manage activity inventory?','Tisonik can connect engagement to inventory, but the property’s reservation or activity system remains the system of record.'],['Can campaigns be limited to certain guests?','Yes. Approved audience criteria can be used for campaign eligibility.'],['Does it support all-inclusive resorts?','Yes. The engagement value remains even when a specific activity is included rather than paid; ancillary revenue is only one outcome.']],related:[['Hotels & Resorts','/hotels-resorts/'],['Guest participation','/guest-participation/'],['Hotel ancillary revenue','/hotel-ancillary-revenue/']]},
'hotel-upselling-software':{title:'Hotel Upselling Software with Guest Context | Tisonik',desc:'Hotel upselling software that uses guest engagement and stay context to create relevant ancillary opportunities without turning every touchpoint into a sales message.',eyebrow:'Hotel upselling software',h1:'Make the next offer fit the guest moment',lead:'Tisonik treats upselling as an outcome of guest engagement—not the starting point. Service state, expressed interest and participation context help determine when a commercial opportunity is appropriate.',tags:['Hotel upselling software','Guest context','Ancillary revenue'],problems:['High message volume can reduce attention and trust.','Upsell systems often know inventory but not the guest’s immediate experience state.','Commercial optimization can conflict with service recovery if systems are disconnected.'],outcomes:['Use declared intent','Prioritize opportunities that match interests or actions the guest has already taken.','Respect service context','Suppress or deprioritize commercial prompts when recovery deserves attention first.','Keep property economics','The property controls inventory, pricing, booking and fulfilment.'],workflow:['Signal','Guest participates, expresses an interest or reaches a relevant journey moment.','Eligibility','Tisonik checks the engagement and service context for a suitable next action.','Handoff','A relevant paid opportunity sends the guest into the property-owned booking path.'],faq:[['Does Tisonik dynamically price hotel inventory?','No. Tisonik does not need to own pricing. It can use approved inventory and eligibility context from the property.'],['What can be upsold?','Typical categories include upgrades, spa, dining, premium activities, transfers and other property-defined ancillary services.'],['Can offers be measured?','Yes. The integration can preserve referral or attribution events for pilot measurement.']],related:[['Hotel ancillary revenue','/hotel-ancillary-revenue/'],['Ancillary revenue','/ancillary-revenue/'],['Hotels & Resorts','/hotels-resorts/']]},
'hotel-ancillary-revenue':{title:'Hotel Ancillary Revenue Platform | Tisonik',desc:'Connect hotel guest engagement to relevant ancillary revenue opportunities across upgrades, spa, dining, activities and other property-owned services.',eyebrow:'Hotel ancillary revenue',h1:'Turn guest intent into relevant property revenue',lead:'Tisonik connects what a guest does and expresses during the stay to the ancillary opportunities a hotel or resort can fulfil—without taking over the transaction.',tags:['Hotel ancillary revenue','Resort revenue','Relevant offers'],problems:['Ancillary demand is time-sensitive and distributed across outlets.','Guests may not know what is available at the right moment.','Broad promotions create exposure but weak relevance.'],outcomes:['Create timely discovery','Surface property services when guest context makes them genuinely relevant.','Protect the guest experience','Coordinate commercial actions with participation and service recovery state.','Improve attribution','Measure the engagement-to-handoff journey without replacing existing booking systems.'],workflow:['Context','Use stay stage, declared interest or participation as an approved signal.','Match','Select a property-defined opportunity that fits the context.','Convert','Hand off to the property’s reservation or checkout environment and preserve attribution.'],faq:[['Is ancillary revenue the primary Tisonik category?','No. Tisonik is a guest engagement platform. Ancillary revenue is one of three core outcomes alongside engagement and service recovery.'],['Can resorts use it for included activities?','Yes. Participation itself can be the objective; a commercial handoff is optional.'],['Does Tisonik process payments?','The preferred architecture leaves payment processing with the hotel or resort.']],related:[['Hotel upselling software','/hotel-upselling-software/'],['Hotels & Resorts','/hotels-resorts/'],['Promotions & rewards','/promotions-and-rewards/']]},
'solutions':{title:'Guest Engagement Solutions | Tisonik',desc:'Explore Tisonik solutions for guest participation, service recovery, crew and staff recognition, feedback, ancillary revenue, promotions and paperless campaigns.',eyebrow:'Solutions',h1:'Seven workflows. Three business outcomes.',lead:'Tisonik organizes guest engagement around practical workflows that improve participation, help teams recover service and create relevant revenue opportunities.',tags:['Engage','Recover','Grow'],problems:['Point solutions create separate guest journeys and staff queues.','Operational signals are hard to compare when each feature has its own data model.','New engagement ideas become integration projects instead of configurable workflows.'],outcomes:['Engage','Participation, recognition, feedback, promotions and live campaigns.','Recover','Structured issue lifecycle with live guest signals and post-recovery measurement.','Grow','Ancillary opportunities informed by context instead of generic broadcast.'],workflow:['Choose a workflow','Start with the business problem, not a feature catalogue.','Configure the role model','Define which guest and staff roles can create, view or act on each signal.','Pilot and expand','Measure one property or sailing, then add workflows and integrations deliberately.'],faq:[['Do we need every solution at launch?','No. Tisonik is intended to support modular pilots.'],['Are cruise and hotel workflows identical?','The operating model is shared, while terminology, roles and integrations adapt to the vertical.'],['Can the same platform support both a cruise group and hotel group?','Yes at platform level, while customer environments remain separately configured and governed.']],related:[['Guest participation','/guest-participation/'],['Service recovery','/service-recovery/'],['Ancillary revenue','/ancillary-revenue/']]},
'guest-participation':{title:'Guest Participation Platform | Tisonik',desc:'Increase guest participation with paperless check-ins, polls, trivia, campaigns and activity engagement for cruise lines, hotels and resorts.',eyebrow:'Engage',h1:'Make participation easy enough to happen in the moment',lead:'Tisonik turns live activities and guest moments into simple digital actions—join, check in, vote, answer, complete or enter—without paper slips or manual reconciliation.',tags:['Participation','Digital check-in','Live campaigns'],problems:['Paper participation creates queues, manual entry and reconciliation.','Activity teams lack a reusable campaign engine.','Guests disengage when every activity requires a different flow.'],outcomes:['Reuse one engine','Support check-ins, polls, trivia, flash draws and other participation formats with a shared campaign lifecycle.','Keep eligibility controlled','Use verified guest context and approved targeting rather than anonymous public entries.','Measure live adoption','Give staff live counts and status controls during the activity.'],workflow:['Create','Staff creates a draft campaign with timing, type, eligibility and prize rules if applicable.','Go live','Guests see and complete the relevant participation action.','Close and measure','End entries, publish results or run a secure server-side draw when the campaign type requires it.'],faq:[['Can one guest enter multiple times?','The current pilot enforces one verified passenger entry per campaign. Production rules can be adapted by campaign type.'],['Does participation require a purchase?','No purchase is required by default.'],['Can campaigns be scheduled?','The campaign lifecycle supports draft, scheduled, live, closed and completed/drawn states.']],related:[['Digital raffles & campaigns','/digital-raffles-and-campaigns/'],['Cruise guest engagement','/cruise-guest-engagement/'],['Resort app','/resort-app/']]},
'service-recovery':{title:'Guest Service Recovery Software | Tisonik',desc:'Guest service recovery software for cruise lines, hotels and resorts with live issue routing, ownership, resolution and post-recovery measurement.',eyebrow:'Recover',h1:'Close the loop between a service issue and the guest’s actual recovery',lead:'Tisonik gives service teams a structured path from signal to ownership to resolution, then asks the guest whether the experience really improved.',tags:['Service recovery','Issue routing','Post-recovery pulse'],problems:['Complaints can be acknowledged without clear ownership.','Operational closure is often mistaken for guest recovery.','Post-stay feedback cannot rescue an active stay or sailing.'],outcomes:['Create accountable ownership','Track acknowledgement, assignment and resolution states across the workflow.','Measure the guest outcome','Use a post-recovery pulse after resolution.','Connect recovery to the wider journey','Avoid treating service recovery as a separate case-management island.'],workflow:['Detect','A guest submits a service issue or a low experience signal creates a recovery path.','Own','The appropriate service team acknowledges and assigns responsibility.','Verify','After resolution, the guest receives a short post-recovery pulse.'],faq:[['Is Tisonik a full hotel ticketing system?','No. It can operate as a focused recovery layer or integrate with broader service-management systems.'],['Can recovery start from feedback?','Yes. Contextual low scores can trigger or connect to a service issue.'],['Can staff see all guest data?','Role-based access should expose only the data needed for each operational responsibility.']],related:[['Guest feedback','/guest-feedback/'],['Cruise service recovery','/cruise-service-recovery/'],['Hotel guest experience software','/hotel-guest-experience-software/']]},
'crew-and-staff-recognition':{title:'Guest-to-Staff Recognition Software | Tisonik',desc:'Capture structured positive guest recognition for cruise crew and hotel or resort staff, with contextual reasons and operational summaries.',eyebrow:'Engage',h1:'Capture the positive service moments that normally disappear',lead:'Tisonik lets verified guests recognize crew or staff with structured reasons, creating a positive signal that can be measured without turning employees into a public rating leaderboard.',tags:['Crew recognition','Staff recognition','Positive signals'],problems:['Great service is often remembered by the guest but never captured by the organization.','Open-text praise is difficult to aggregate and route.','Public star ratings can distort recognition and create unhealthy ranking dynamics.'],outcomes:['Make recognition easy','Use named or roster-linked staff identity with predefined reasons.','Keep context useful','Preserve property/sailing and service context without public employee scoring.','Create positive summaries','Give teams and individuals structured recognition records that can complement existing HR processes.'],workflow:['Identify','Guest selects or scans the relevant crew/staff identity within approved rules.','Recognize','Guest chooses a small number of predefined recognition reasons.','Summarize','Tisonik aggregates recognition by staff member, guest count and operating context.'],faq:[['Is this an employee performance system?','No. Recognition is a guest signal. Employment and compensation decisions remain with the operator.'],['Can guests write unrestricted comments?','The core model uses predefined reasons to improve consistency and reduce moderation burden.'],['Does Tisonik use facial recognition?','No. The design does not require facial recognition.']],related:[['Guest feedback','/guest-feedback/'],['Tisonik Cruise','/cruise/'],['Hotels & Resorts','/hotels-resorts/']]},
'guest-feedback':{title:'Real-Time Guest Feedback Platform | Tisonik',desc:'Collect short, contextual guest feedback for cruise lines, hotels and resorts and route it into recognition, recovery and experience measurement.',eyebrow:'Engage + Recover',h1:'Ask less. Learn sooner. Act while it matters.',lead:'Tisonik focuses on short contextual signals that can change an active experience rather than waiting for a long post-stay or post-cruise survey.',tags:['Guest feedback','Experience Pulse','Real-time signals'],problems:['Long forms create low completion and delayed insight.','Feedback dashboards can separate insight from the team responsible for action.','Positive and negative signals often follow completely different systems.'],outcomes:['Increase response likelihood','Use a 1–5 pulse or structured choice when that is enough.','Route by intent','High scores can support recognition; low scores can support recovery.','Preserve measurement','Aggregate signals by department, property or sailing for operational review.'],workflow:['Prompt','Ask a small contextual question at an appropriate moment.','Classify','Interpret the signal in the guest’s current service and engagement context.','Route','Send the signal to recognition, recovery, measurement or another configured workflow.'],faq:[['Does Tisonik replace NPS?','Not necessarily. Tisonik can complement broader survey programs with in-experience operational signals.'],['Can guests submit text?','Text can be enabled where needed, but the core philosophy is to use structured responses whenever possible.'],['Can feedback be department-specific?','Yes. The cruise pilot includes department-level pulse concepts, and hotel/resort deployment can map to property departments.']],related:[['Service recovery','/service-recovery/'],['Crew & staff recognition','/crew-and-staff-recognition/'],['Guest engagement platform','/guest-engagement-platform/']]},
'ancillary-revenue':{title:'Ancillary Revenue Platform for Guest Engagement | Tisonik',desc:'Connect guest engagement signals to relevant ancillary revenue opportunities for cruise lines, hotels and resorts while keeping inventory and checkout with the operator.',eyebrow:'Grow',h1:'Revenue should follow relevance',lead:'Tisonik creates commercial opportunities from declared interests, participation and guest context—while the cruise line, hotel or resort remains the merchant and fulfilment owner.',tags:['Ancillary revenue','Guest intent','Operator-owned checkout'],problems:['Commercial messaging can become disconnected from the guest’s actual context.','Engagement and booking attribution often live in separate systems.','Revenue pressure can damage experience when unresolved service issues are ignored.'],outcomes:['Use better timing','Create opportunities from signals the guest has voluntarily provided.','Protect service priority','Coordinate commercial actions with recovery state and guest context.','Preserve operator control','Use existing inventory, pricing, payment and fulfilment systems.'],workflow:['Intent','Guest expresses interest or takes an engagement action.','Relevance','Tisonik selects a configured opportunity that fits the context.','Handoff','The guest continues in the operator’s booking environment with agreed attribution.'],faq:[['Does Tisonik take a percentage of every transaction?','Commercial terms can be structured for pilots, but the product architecture does not require Tisonik to become merchant of record.'],['Can revenue opportunities be disabled?','Yes. A deployment can use engagement and recovery without enabling commercial workflows.'],['Can Tisonik use real-time inventory?','Production integrations can consume approved availability or inventory signals from operator systems.']],related:[['Cruise onboard revenue','/cruise-onboard-revenue/'],['Hotel ancillary revenue','/hotel-ancillary-revenue/'],['Hotel upselling software','/hotel-upselling-software/']]},
'promotions-and-rewards':{title:'Guest Promotions & Rewards Platform | Tisonik',desc:'Create controlled guest promotions and rewards for cruise lines, hotels and resorts that connect to verified participation and relevant engagement context.',eyebrow:'Engage + Grow',h1:'Make promotions part of the guest journey, not a broadcast layer',lead:'Tisonik gives marketing and revenue teams controlled ways to connect promotions, rewards and limited-time opportunities to verified guest participation.',tags:['Promotions','Rewards','Guest targeting'],problems:['Generic promotions compete with operational and service messaging.','Campaign teams lack a consistent way to connect eligibility to guest participation.','Promotion performance can be difficult to separate from general app traffic.'],outcomes:['Target deliberately','Use approved guest segment or participation criteria.','Connect reward to action','Tie a reward, prize or opportunity to a clear engagement flow.','Measure campaign response','Track eligible participation and resulting handoff events.'],workflow:['Define','Set audience, timing, action and reward or offer rules.','Launch','Surface the campaign in the relevant guest context.','Review','Measure participation and commercial or engagement outcomes.'],faq:[['Can Marketing and Revenue have separate roles?','Yes. The cruise pilot includes separate Marketing and Sales/Revenue staff roles.'],['Can promotions include alcohol?','Prize and promotion configuration should respect age and operator policy; the pilot supports alternate non-alcoholic prize treatment.'],['Does Tisonik provide loyalty points?','Tisonik can integrate with a loyalty program, but it is not intended to replace the operator’s loyalty ledger.']],related:[['Digital raffles & campaigns','/digital-raffles-and-campaigns/'],['Ancillary revenue','/ancillary-revenue/'],['Guest participation','/guest-participation/']]},
'digital-raffles-and-campaigns':{title:'Digital Raffles, Draws & Guest Campaigns | Tisonik',desc:'Run paperless digital raffles, polls, trivia, check-ins and guest participation campaigns with verified eligibility and secure server-side draws.',eyebrow:'Engage',h1:'Replace paper slips with a reusable live participation engine',lead:'Tisonik supports digital campaign formats that operations, activities and marketing teams can run repeatedly without manual entry or opaque winner selection.',tags:['Digital raffle','Paperless draw','Live campaign'],problems:['Paper raffles create queues, manual data entry and disputes.','One-off campaign tools are hard to reuse across activities.','Winner selection needs a transparent, auditable process.'],outcomes:['Use verified entries','Tie participation to approved guest identity rather than anonymous paper slips.','Run secure draws','Select winners server-side from qualified entries with recorded ranks and alternate prize logic.','Reuse campaign types','Support draws, polls, trivia, digital check-ins and activity participation through one lifecycle.'],workflow:['Open','Campaign moves from draft or scheduled state to live.','Enter','Eligible guests complete the required action and receive a privacy-safe entry code where relevant.','Draw or end','Staff closes participation and the server produces results based on campaign rules.'],faq:[['Is purchase required?','No purchase is required by default.'],['Can there be multiple winners?','Yes. Winner count is configurable for draw campaigns.'],['How are minors handled?','Age eligibility and alternate prizes can be configured according to operator policy.']],related:[['Guest participation','/guest-participation/'],['Promotions & rewards','/promotions-and-rewards/'],['Cruise guest feedback','/cruise-guest-feedback/']]}
}

const nav=`<header class="site-header"><div class="shell nav"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true"></span>Tisonik</a><nav class="nav-links" aria-label="Main navigation"><a href="/guest-engagement-platform/">Platform</a><a href="/cruise/">Cruise</a><a href="/hotels-resorts/">Hotels & Resorts</a><a href="/solutions/">Solutions</a></nav><div class="nav-actions"><a class="btn btn-secondary hide-mobile" href="/pilot-simulator/">View pilot</a><a class="btn btn-primary" href="/request-pilot/">Request a pilot</a><button class="menu-btn" aria-label="Open menu" aria-expanded="false">☰</button></div></div></header>`
const footer=`<footer class="site-footer"><div class="shell"><div class="footer-grid"><div class="footer-brand"><a class="brand" href="/"><span class="brand-mark"></span>Tisonik</a><p>Guest engagement platform for cruise lines, hotels and resorts. Better guest moments. Faster recovery. More revenue.</p></div><div class="footer-col"><b>Platform</b><a href="/guest-engagement-platform/">Guest engagement platform</a><a href="/solutions/">Solutions</a><a href="/request-pilot/">Request a pilot</a></div><div class="footer-col"><b>Industries</b><a href="/cruise/">Cruise lines</a><a href="/hotels-resorts/">Hotels & Resorts</a><a href="/hotel-guest-experience-software/">Hotel guest experience</a></div><div class="footer-col"><b>Legal</b><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><a href="/cookies/">Cookies & storage</a><a href="/imprint/">Imprint</a></div></div><div class="footer-bottom"><span>© 2026 Tisonik · A product of PlanetHike OÜ</span><span>Engage · Recover · Grow</span></div></div></footer>`

const head=(title,desc,path,robots='index,follow,max-image-preview:large')=>`<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#071c24"><meta name="robots" content="${robots}"><title>${title}</title><meta name="description" content="${desc}"><link rel="canonical" href="${SITE}${path}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="manifest" href="/site.webmanifest"><link rel="stylesheet" href="/marketing.css"><meta property="og:type" content="website"><meta property="og:site_name" content="Tisonik"><meta property="og:title" content="${title}"><meta property="og:description" content="${desc}"><meta property="og:url" content="${SITE}${path}"><meta name="twitter:card" content="summary"><script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Organization','name':'Tisonik','url':SITE,'description':'Guest engagement platform for cruise lines, hotels and resorts.'},{'@type':'SoftwareApplication','name':'Tisonik','applicationCategory':'BusinessApplication','operatingSystem':'Web','description':'Guest engagement platform connecting participation, service recovery and ancillary revenue for cruise lines, hotels and resorts.'}]})}</script></head><body>`

const renderOutcomes=(items)=>{const out=[];for(let i=0;i<items.length;i+=2)out.push(`<div class="outcome"><b>${items[i]}</b><p>${items[i+1]}</p></div>`);return out.join('')}
const renderWorkflow=(items)=>{const out=[];for(let i=0;i<items.length;i+=2)out.push(`<div class="workflow-step"><div><b>${items[i]}</b><p>${items[i+1]}</p></div></div>`);return out.join('')}
const renderPage=(slug,p)=>`${head(p.title,p.desc,`/${slug}/`)}${nav}<main><section class="page-hero"><div class="shell inner"><div class="eyebrow">${p.eyebrow}</div><h1>${p.h1}</h1><p>${p.lead}</p><div class="page-band">${p.tags.map(x=>`<span>${x}</span>`).join('')}</div></div></section><section class="section"><div class="shell content-grid"><div><div class="eyebrow">Why this matters</div><h2>Engagement only creates value when somebody can act on it.</h2><p>Tisonik is designed around the operating moment: what the guest is trying to do, what the team needs to know, and what the next useful action should be.</p><div class="kicker-card">The objective is not more messages. It is a better connection between guest intent, service action and measurable outcome.</div></div><div class="stack">${p.problems.map((x,i)=>`<div class="stack-card"><strong>${String(i+1).padStart(2,'0')} · ${x}</strong></div>`).join('')}</div></div></section><section class="section section-tint"><div class="shell"><div class="section-head"><div><div class="eyebrow">Outcomes</div><h2>What changes operationally</h2></div><p>Tisonik links guest-facing interactions to operational and commercial follow-through, rather than treating engagement as an isolated front-end feature.</p></div><div class="outcomes">${renderOutcomes(p.outcomes)}</div></div></section><section class="section"><div class="shell content-grid"><div><div class="eyebrow">Workflow</div><h2>From signal to action</h2><p>The platform is deliberately structured so each interaction has a clear state, owner and next step.</p></div><div class="workflow">${renderWorkflow(p.workflow)}</div></div></section><section class="section section-dark"><div class="shell"><div class="section-head"><div><div class="eyebrow">Platform fit</div><h2>Built for cruise lines, hotels and resorts</h2></div><p>Tisonik is not trying to become the PMS, cruise app, POS, booking engine or payment processor. It connects guest engagement to those systems through a focused operating layer.</p></div><div class="proof-strip"><div class="proof-item"><strong>White-label</strong><span>Operator brand stays primary</span></div><div class="proof-item"><strong>Role-based</strong><span>Guest and staff workflows stay separated</span></div><div class="proof-item"><strong>API-oriented</strong><span>Host systems remain systems of record</span></div><div class="proof-item"><strong>Pilot-first</strong><span>Start bounded, measure, then expand</span></div></div></div></section><section class="section"><div class="shell"><div class="section-head"><div><div class="eyebrow">FAQ</div><h2>Common questions</h2></div><p>Commercial pilots should be explicit about scope, integration and the outcome being measured.</p></div><div class="faq">${p.faq.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div><div class="related" style="margin-top:28px">${p.related.map(([label,url])=>`<a href="${url}">${label} →</a>`).join('')}</div></div></section><section class="section"><div class="shell"><div class="cta-band"><div><h2>See the workflow on a real pilot.</h2><p>Choose a cruise, hotel or resort use case, define the operating roles and measure participation, recovery and commercial outcomes.</p></div><a class="btn btn-secondary" href="/request-pilot/">Request a pilot</a></div></div></section></main>${footer}<script src="/marketing.js" defer></script></body></html>`

const home=()=>`${head('Tisonik | Guest Engagement Platform for Cruise Lines, Hotels & Resorts','Tisonik helps cruise lines, hotels and resorts drive guest participation, recognize positive moments, recover service issues and create relevant revenue opportunities.','/')} ${nav}<main><section class="hero"><div class="shell hero-grid"><div><div class="eyebrow">Guest engagement platform for cruise lines, hotels & resorts</div><h1>Turn guest engagement into better experiences and more revenue</h1><p class="lead">Tisonik helps cruise lines, hotels and resorts increase guest participation, recognize positive moments, recover service issues in real time and create more relevant revenue opportunities.</p><div class="hero-actions"><a class="btn btn-primary" href="/request-pilot/">Request a pilot</a><a class="btn btn-secondary" href="/guest-engagement-platform/">Explore the platform</a></div><div class="micro-proof"><span><i></i>White-label</span><span><i></i>Role-based operations</span><span><i></i>Built for existing guest journeys</span></div></div><div class="hero-visual" aria-label="Illustrative Tisonik dashboard"><div class="visual-backdrop"></div><div class="visual-panel visual-main"><div class="visual-top"><strong>Guest signal stream</strong><span class="chip">Live</span></div><div class="signal-list"><div class="signal"><div class="signal-icon">E</div><div><b>Participation</b><small>Guest joined a live activity</small></div><em>Engage</em></div><div class="signal"><div class="signal-icon">R</div><div><b>Experience pulse</b><small>Low score routed to service team</small></div><em>Recover</em></div><div class="signal"><div class="signal-icon">G</div><div><b>Relevant opportunity</b><small>Interest matched to operator inventory</small></div><em>Grow</em></div></div></div><div class="visual-panel visual-small"><div class="visual-top"><strong>Engagement health</strong><span class="chip">Illustrative</span></div><h3>One operating layer</h3><div class="pulse"><span></span></div><p>Participation, recovery and revenue signals remain connected instead of living in separate point tools.</p></div></div></div></section><section class="section section-dark"><div class="shell"><div class="section-head"><div><div class="eyebrow">The platform</div><h2>Engage. Recover. Grow.</h2></div><p>Tisonik organizes guest engagement around three outcomes enterprise operators can actually measure.</p></div><div class="cards-3"><div class="card"><div class="card-num">01</div><h3>Engage</h3><p>Participation, recognition, feedback, promotions and paperless live campaigns create useful reasons for guests to interact.</p><a class="card-link" href="/guest-participation/">Explore engagement →</a></div><div class="card"><div class="card-num">02</div><h3>Recover</h3><p>Low experience signals become acknowledged, assigned and measurable service recovery workflows while the guest is still present.</p><a class="card-link" href="/service-recovery/">Explore recovery →</a></div><div class="card"><div class="card-num">03</div><h3>Grow</h3><p>Relevant guest context creates better ancillary opportunities without taking inventory, pricing or checkout away from the operator.</p><a class="card-link" href="/ancillary-revenue/">Explore revenue →</a></div></div></div></section><section class="section"><div class="shell"><div class="section-head"><div><div class="eyebrow">Two verticals</div><h2>Designed for high-dwell guest environments</h2></div><p>Cruise lines, hotels and resorts share the same core opportunity: the guest is already inside the experience, but engagement and operational response are fragmented.</p></div><div class="verticals"><a class="vertical-card cruise" href="/cruise/"><span>Tisonik Cruise</span><h3>Cruise lines</h3><p>Passenger participation, crew recognition, onboard service recovery and relevant revenue in a sailing-scoped engagement layer.</p></a><a class="vertical-card hotel" href="/hotels-resorts/"><span>Tisonik Hotels & Resorts</span><h3>Hotels & Resorts</h3><p>In-stay participation, staff recognition, service intelligence and ancillary opportunities across the property journey.</p></a></div></div></section><section class="section section-tint"><div class="shell"><div class="section-head"><div><div class="eyebrow">How it works</div><h2>Guest signal → operational action → measurable outcome</h2></div><p>The same signal should not go to every team. Tisonik gives each interaction an intentional route.</p></div><div class="flow"><div class="flow-step"><small>01 · Signal</small><h3>Capture the moment</h3><p>A guest joins, recognizes, rates, checks in, reports an issue or expresses an interest.</p></div><div class="flow-step"><small>02 · Action</small><h3>Route it correctly</h3><p>The platform sends the signal to engagement, service recovery, recognition or a relevant commercial workflow.</p></div><div class="flow-step"><small>03 · Outcome</small><h3>Measure what changed</h3><p>Participation, recovery, follow-up and attribution can be measured at property or sailing level.</p></div></div></div></section><section class="section"><div class="shell content-grid"><div><div class="eyebrow">Architecture</div><h2>Not another standalone guest app</h2><p>Tisonik is designed to fit the operator’s existing digital relationship. The cruise line, hotel or resort keeps identity, inventory, pricing, payments and the core guest experience.</p><div class="hero-actions"><a class="btn btn-primary" href="/guest-engagement-platform/">Platform details</a><a class="btn btn-secondary" href="/pilot-simulator/">Open cruise pilot</a></div></div><div class="stack"><div class="stack-card"><strong>Existing guest identity</strong><span>Use approved host context instead of asking the guest to create another account.</span></div><div class="stack-card"><strong>Existing commerce stack</strong><span>Tisonik creates relevance and attribution; the operator owns booking and fulfilment.</span></div><div class="stack-card"><strong>Existing operations</strong><span>Role-based workflows connect to the teams that can actually act.</span></div></div></div></section><section class="section"><div class="shell"><div class="cta-band"><div><h2>Start with one operating problem.</h2><p>Pilot participation, recovery or revenue on one sailing or property, define the KPIs in advance and expand only when the workflow earns it.</p></div><a class="btn btn-secondary" href="/request-pilot/">Request a pilot</a></div></div></section></main>${footer}<script src="/marketing.js" defer></script></body></html>`

const requestPilot=()=>`${head('Request a Tisonik Pilot | Cruise Lines, Hotels & Resorts','Request a Tisonik pilot for a cruise line, hotel or resort. Define the use case, operating footprint and pilot objectives.','/request-pilot/')} ${nav}<main><section class="page-hero"><div class="shell inner"><div class="eyebrow">Request a pilot</div><h1>Start with one measurable guest journey</h1><p>A strong Tisonik pilot is deliberately bounded: one sailing, property or property set; a small number of workflows; defined staff owners; and KPIs agreed before launch.</p></div></section><section class="section"><div class="shell content-grid"><div><div class="eyebrow">Pilot design</div><h2>What we want to learn</h2><div class="stack"><div class="stack-card"><strong>Engagement</strong><span>Do guests participate more when the action is low-friction and contextually relevant?</span></div><div class="stack-card"><strong>Recovery</strong><span>Can teams identify, own and improve service issues before the guest leaves?</span></div><div class="stack-card"><strong>Commercial relevance</strong><span>Can voluntary guest context improve the quality of ancillary opportunities?</span></div></div></div><form id="pilot-request-form" class="form-card"><div class="form-grid"><div class="field"><label for="name">Name *</label><input id="name" name="name" autocomplete="name" required maxlength="120"></div><div class="field"><label for="workEmail">Work email *</label><input id="workEmail" name="workEmail" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="company">Company *</label><input id="company" name="company" autocomplete="organization" required maxlength="180"></div><div class="field"><label for="role">Role</label><input id="role" name="role" autocomplete="organization-title" maxlength="120"></div><div class="field"><label for="segment">Business *</label><select id="segment" name="segment" required><option value="">Select</option><option value="cruise">Cruise line</option><option value="hotel_resort">Hotel or resort</option><option value="both">Cruise + hotels/resorts</option></select></div><div class="field"><label for="footprint">Ships / properties</label><input id="footprint" name="footprint" placeholder="e.g. 12 ships or 45 properties" maxlength="160"></div><div class="field full"><label for="message">What would you like to pilot?</label><textarea id="message" name="message" maxlength="2000" placeholder="Use case, current guest journey, target property/sailing and the outcome you want to improve."></textarea></div><div class="field honeypot" aria-hidden="true"><label for="website">Website</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><div class="field full"><label class="check"><input type="checkbox" name="consent" value="yes" required><span>I agree that Tisonik / PlanetHike OÜ may use these business contact details to respond to this pilot request. See the <a href="/privacy/"><u>Privacy Policy</u></a>.</span></label></div><div class="field full"><button class="btn btn-primary" type="submit">Request a pilot</button><div class="form-status" aria-live="polite"></div></div></div></form></div></section></main>${footer}<script src="/marketing.js" defer></script></body></html>`

const legalPage=(kind,title,lead,body)=>`${head(`${title} | Tisonik`,lead,`/${kind}/`)}${nav}<main><section class="page-hero"><div class="shell legal"><div class="eyebrow">Legal</div><h1>${title}</h1><p>${lead}</p><div class="page-band"><span>Last updated ${updated}</span></div></div></section><section class="section"><article class="shell legal">${body}</article></section></main>${footer}<script src="/marketing.js" defer></script></body></html>`

const imprint=()=>legalPage('imprint','Imprint','Legal operator information for Tisonik.',`<h2>Operator information</h2><p><strong>Tisonik</strong> is a product and trade name operated by <strong>PlanetHike OÜ</strong>.</p><dl><div><dt>Legal entity</dt><dd>PlanetHike OÜ</dd></div><div><dt>Registered office</dt><dd>Järvevana tee 9, Tallinn, 11314, Estonia</dd></div><div><dt>Registry code</dt><dd>17233027</dd></div><div><dt>Register</dt><dd>Estonian Business Register</dd></div><div><dt>Legal representative</dt><dd>Tichi Mbanwie</dd></div><div><dt>Email</dt><dd><a href="mailto:hello@planethike.org">hello@planethike.org</a></dd></div></dl><h2>Service responsibility</h2><p>PlanetHike OÜ is responsible for the Tisonik website, product demonstrations and original product materials. Unless a specific customer relationship is expressly identified, example brands, properties, ships, people, metrics and interfaces are illustrative and do not imply affiliation.</p><p>When Tisonik is deployed by a cruise line, hotel or resort, the operator remains responsible for its guest relationship, physical operations, safety procedures, staff management, inventory, pricing, bookings, payments and fulfilment.</p><h2>Intellectual property</h2><p>Unless otherwise stated, Tisonik software, product concepts, interface designs, text, graphics and documentation are owned by PlanetHike OÜ or used under licence. Third-party marks remain the property of their respective owners.</p>`)
const privacy=()=>legalPage('privacy','Privacy Policy','How Tisonik handles website, pilot and platform data.',`<h2>1. Scope</h2><p>This policy explains how PlanetHike OÜ, operating Tisonik, handles personal data on this website and in controlled product pilots. Customer deployments may include customer-specific privacy information reflecting the cruise line, hotel or resort systems and legal responsibilities.</p><h2>2. Controller and processor roles</h2><p>PlanetHike OÜ is controller for website and direct business enquiries, including pilot requests. In a typical white-label customer deployment, the cruise line, hotel or resort determines the purposes of guest and staff processing and acts as controller; PlanetHike OÜ generally processes that data on documented instructions as processor. Contractual documents define the exact allocation.</p><h2>3. Website and pilot-request data</h2><p>When you request a pilot, we may process name, work email, company, role, business segment, operating footprint, message, source page, basic technical information and a one-way hash of the submitting network address for abuse-rate limiting. We use these data to respond to the request, qualify the use case, administer the enterprise relationship and protect the form from abuse.</p><h2>4. Platform data</h2><p>Depending on customer configuration, Tisonik may process verified guest/stay or sailing context, selected guest profile information, participation actions, recognition signals, experience scores, service recovery status, campaign entries, relevant commerce handoff events and technical data required to operate the service. Production deployments should minimize data to the enabled workflows.</p><h2>5. Legal bases</h2><p>Relevant GDPR legal bases may include steps requested before entering a business relationship, legitimate interests in enterprise communications and service security, contractual necessity, legal obligations and consent where an optional guest feature requires it.</p><h2>6. Recipients and transfers</h2><p>We do not sell personal data. Data may be available to authorized PlanetHike OÜ personnel, the relevant customer and approved infrastructure or professional service providers where necessary. International transfers use an applicable lawful transfer mechanism where required.</p><h2>7. Retention</h2><p>Business enquiries are retained only as long as needed for the commercial relationship, legal obligations and reasonable follow-up. Customer deployment retention is defined with the customer. Tisonik’s design principle is to keep proximity identifiers and offline queues short-lived and avoid collecting payment-card data.</p><h2>8. Your rights</h2><p>Where GDPR applies, you may have rights of access, correction, erasure, restriction, portability and objection, and may withdraw consent where processing relies on consent. For PlanetHike OÜ-controlled data contact <a href="mailto:hello@planethike.org">hello@planethike.org</a> with the subject “Privacy request – Tisonik”.</p><h2>9. Security and changes</h2><p>We use data minimization, role-based access, secure transport, restricted database permissions and bounded interaction patterns. We may update this policy as the product and customer integrations evolve.</p>`)
const terms=()=>legalPage('terms','Terms of Service','Terms for the Tisonik website, demonstrations and partner-deployed platform.',`<h2>1. Operator and scope</h2><p>These Terms govern access to the Tisonik website and demonstrations. Tisonik is operated by PlanetHike OÜ, registry code 17233027, Järvevana tee 9, Tallinn, 11314, Estonia. Signed customer agreements prevail over these public Terms where they conflict.</p><h2>2. White-label platform</h2><p>Tisonik is designed to sit within or alongside a cruise line, hotel or resort digital environment. The operator remains responsible for physical operations, safety, guest contracts, staff management, inventory, pricing, bookings, payments, refunds and fulfilment.</p><h2>3. Demonstrations and pilots</h2><p>Demo people, brands, metrics, properties, ships and commercial figures may be illustrative. Pilot access may be limited to verified test identities, a property, sailing or approved staff role. Users must not bypass access controls, manipulate campaign entries or impersonate another user.</p><h2>4. Guest interaction</h2><p>Tisonik is not an unrestricted social network or dating service. Where structured guest-to-guest interaction is enabled, the product intentionally constrains first contact and should preserve blocking, reporting and operator safety controls.</p><h2>5. Service recovery</h2><p>Service recovery features are not emergency channels. Medical, safety, security and other urgent issues must use the customer’s designated emergency procedures. Submitting a service issue does not guarantee a refund, remedy or response time.</p><h2>6. Commerce</h2><p>Tisonik may surface relevant customer-owned offers or inventory and record agreed attribution events. Unless expressly agreed otherwise, the customer or its designated merchant controls pricing, checkout, payment, refunds and fulfilment.</p><h2>7. Intellectual property</h2><p>Tisonik software, design, documentation, branding and original content are owned by PlanetHike OÜ or its licensors. No commercial reuse, reverse engineering or redistribution is permitted except where applicable law expressly allows it.</p><h2>8. Availability and liability</h2><p>Connectivity, host systems, device capabilities and maintenance can affect availability. Tisonik does not guarantee that guests will participate, respond, purchase or obtain a specific service outcome. Liability is limited to the extent permitted by applicable law; non-excludable statutory liability remains unaffected.</p><h2>9. Governing law</h2><p>These public Terms are governed by Estonian law without prejudice to mandatory protections that apply to you. Enterprise disputes follow the signed customer agreement.</p><h2>10. Contact</h2><p>Questions: <a href="mailto:hello@planethike.org">hello@planethike.org</a>.</p>`)
const cookies=()=>legalPage('cookies','Cookie & Local Storage Policy','What the current Tisonik website and pilot store on your device.',`<h2>1. Current public website</h2><p>The current Tisonik marketing website does not intentionally use advertising cookies, cross-site tracking pixels or non-essential analytics cookies. It uses ordinary browser functionality required to render pages and submit the pilot-request form.</p><h2>2. Pilot simulator</h2><p>The protected pilot simulator may use session storage, Local Storage, Cache Storage and a service worker to preserve pilot authentication state, demonstrate offline queues and cache the application shell. These are functional technologies rather than advertising trackers.</p><h2>3. Customer deployments</h2><p>A cruise line, hotel or resort may use its own authentication, analytics or app-storage technologies around an embedded Tisonik module. The customer’s privacy and cookie information applies to customer-controlled technologies.</p><h2>4. Managing storage</h2><p>You can delete browser storage through your browser or device settings. Clearing essential pilot storage may sign you out, remove queued demonstration actions or require cached files to be downloaded again.</p><h2>5. Changes</h2><p>If Tisonik later adds non-essential analytics or marketing technologies, we will update this page and introduce any consent mechanism required by applicable law before activating them.</p>`)

for(const [slug,p] of Object.entries(pages)){mkdirSync(resolve(root,slug),{recursive:true});writeFileSync(resolve(root,slug,'index.html'),renderPage(slug,p),'utf8')}
writeFileSync(resolve(root,'index.html'),home(),'utf8')
mkdirSync(resolve(root,'request-pilot'),{recursive:true});writeFileSync(resolve(root,'request-pilot/index.html'),requestPilot(),'utf8')
for(const [slug,html] of [['imprint',imprint()],['privacy',privacy()],['terms',terms()],['cookies',cookies()]]){mkdirSync(resolve(root,slug),{recursive:true});writeFileSync(resolve(root,slug,'index.html'),html,'utf8')}

const indexable=['',...Object.keys(pages),'request-pilot','imprint','privacy','terms','cookies']
const sitemap=`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${indexable.map(slug=>`  <url><loc>${SITE}/${slug?`${slug}/`:''}</loc><lastmod>2026-08-18</lastmod></url>`).join('\n')}\n</urlset>\n`
mkdirSync(resolve(root,'public'),{recursive:true});writeFileSync(resolve(root,'public/sitemap.xml'),sitemap,'utf8');writeFileSync(resolve(root,'public/robots.txt'),`User-agent: *\nAllow: /\nDisallow: /pilot-simulator/\nSitemap: ${SITE}/sitemap.xml\n`,'utf8')
console.log(`Generated Tisonik marketing site (${indexable.length} indexable pages).`)
